    "Turn on Listen on the Talk tab. A notification means it is listening.": "Activa Escuchar en la pestaña Hablar. Una notificación significa que está escuchando.",
    "You skipped enrollment. Train it anytime under Settings, then Wake word, and turn Listen on.": "Saltaste la grabación. Puedes entrenarla cuando quieras en Ajustes, Palabra de activación, y activar Escuchar.",
    "Save a voice to continue. On device counts after you tap Use on device.": "Guarda una voz para seguir. En el teléfono cuenta cuando tocas Usar en el teléfono.",
    "Allow the microphone to continue.": "Permite el micrófono para seguir.",
    "Preview finished. In the app this opens the assistant.": "La vista previa ha terminado. En la app esto abre el asistente.",
    "A voice assistant that stays on your phone": "Un asistente de voz que se queda en tu teléfono",
    "Five short steps. About two minutes.": "Cinco pasos cortos. Unos dos minutos.",
    "xAI and OpenAI need a key. On device needs a download. The first one in the list is tried first.": "xAI y OpenAI necesitan una clave. En el teléfono necesita una descarga. Se prueba primero el de arriba.",
    "Needed to hear you, including when the screen is off.": "Hace falta para oírte, también con la pantalla apagada.",
    "Three short recordings. They never leave the phone. You can skip and tap instead.": "Tres grabaciones cortas. No salen del teléfono. Puedes saltarlas y tocar en su lugar.",
    "Add a voice key": "Añadir una clave de voz",
    "Tap Use on device. That adds it to the list. No key.": "Toca Usar en el teléfono. Eso lo añade a la lista. Sin clave.",
    "Leave it first if the phone should answer before a cloud key.": "Déjalo el primero si el teléfono debe responder antes que una clave en la nube.",
    "Download the packs below. Until they finish, Talk uses the next key.": "Descarga los paquetes de abajo. Hasta que terminen, Hablar usa la siguiente clave.",
    "Add another voice if you want a fallback, then tap Next.": "Añade otra voz si quieres un respaldo y luego toca Siguiente.",
    "Each key stays on this phone. xAI is checked before it is stored. If the first voice fails, the next one is tried.": "Cada clave se queda en este teléfono. xAI se comprueba antes de guardarla. Si la primera voz falla, se prueba la siguiente.",
    "Paste the {name} key": "Pega la clave de {name}",
    "Android will show a system prompt. Choose Allow.": "Android mostrará un aviso del sistema. Elige Permitir.",
    "The microphone hears “Hey Grok” and your question. A quiet notification stays up so Android does not switch the microphone off when the screen locks.": "El micrófono oye “Hey Grok” y tu pregunta. Queda una notificación discreta para que Android no apague el micrófono al bloquear la pantalla.",
    "Microphone is blocked. Open Android Settings → Apps → Grok Voice → Permissions, allow Microphone, then come back and tap the button again.": "El micrófono está bloqueado. Abre Ajustes de Android → Aplicaciones → Grok Voice → Permisos, permite el micrófono, vuelve y toca el botón otra vez.",
    "Notifications are off. Listening still works while the app is open. Allow notifications later if you want “Hey Grok” with the screen locked.": "Las notificaciones están apagadas. Escuchar sigue funcionando con la app abierta. Permítelas después si quieres “Hey Grok” con la pantalla bloqueada.",
    "How to talk": "Cómo hablar",
    "Tap the ring": "Toca el anillo",
    "Speak after it says Listening. Tap again to hang up.": "Habla cuando diga Escuchando. Toca otra vez para colgar.",
    "Ask it to do things": "Pídele que haga cosas",
    "Notes, alarms, timers, reminders, and calendar. Each has its own tab after setup.": "Notas, alarmas, temporizadores, recordatorios y calendario. Cada uno tiene su pestaña después del inicio.",
    "Use headphones the first time. On a loudspeaker the microphone hears the reply and Grok answers itself. Echo guard is on so the mic mutes while Grok is talking. Turn it off in Settings, then Debug, if you want to interrupt.": "Usa auriculares la primera vez. En altavoz el micrófono oye la respuesta y Grok se contesta. La protección contra el eco está activa y silencia el micrófono mientras Grok habla. Apágala en Ajustes y luego Depuración si quieres interrumpir.",
    "Enroll “Hey Grok”": "Grabar “Hey Grok”",
    "Record yourself saying “Hey Grok” three times, in a quiet room, holding the phone the way you normally would. The recordings stay on this phone.": "Grábate diciendo “Hey Grok” tres veces, en un sitio tranquilo, con el teléfono como lo sujetas normalmente. Las grabaciones se quedan en este teléfono.",
