    "On-device Talk reads these pinned facts and short notes from recent local sessions. Cloud Talk does not. Wiping this does not delete notes, People, Finance, or voice keys.": "Hablar en el teléfono lee estos datos fijados y las notas cortas de las sesiones recientes. La voz en la nube no. Borrar esto no borra las notas, Personas, Finanzas ni las claves de voz.",
    "I live in Zurich": "Vivo en Zúrich",
    "Tap again. Notes, People, Finance, and voice keys stay.": "Toca otra vez. Las notas, Personas, Finanzas y las claves de voz se quedan.",
    "These are asked only when you turn them on. Notification access and Do Not Disturb open system settings. Call and text history is a separate permission and is not read until you allow it.": "Solo se piden cuando los activas. El acceso a notificaciones y No molestar abren los ajustes del sistema. El historial de llamadas y mensajes es otro permiso y no se lee hasta que lo permites.",
    "An encrypted file of notes, People, and the small on-device memory. Older files have no memory section, so restoring one leaves the memory on this phone. Voice keys stay in the vault unless you include them here. Nothing is uploaded.": "Un archivo cifrado de notas, Personas y la memoria pequeña del teléfono. Los archivos antiguos no tienen sección de memoria, así que restaurar uno deja la memoria de este teléfono. Las claves de voz se quedan en la caja fuerte salvo que las incluyas aquí. No se sube nada.",
