    "Turn on Listen on the Talk tab. A notification means it is listening.": "Schalt Hören im Tab Sprechen ein. Eine Benachrichtigung heißt, dass zugehört wird.",
    "You skipped enrollment. Train it anytime under Settings, then Wake word, and turn Listen on.": "Du hast das Einrichten übersprungen. Trainier es jederzeit unter Einstellungen, dann Weckwort, und schalt Hören ein.",
    "Save a voice to continue. On device counts after you tap Use on device.": "Speichere eine Stimme, um weiterzumachen. Auf dem Telefon zählt, sobald du Auf dem Telefon nutzen tippst.",
    "Allow the microphone to continue.": "Erlaub das Mikrofon, um weiterzumachen.",
    "Preview finished. In the app this opens the assistant.": "Die Vorschau ist fertig. In der App öffnet das den Assistenten.",
    "A voice assistant that stays on your phone": "Ein Sprachassistent, der auf deinem Telefon bleibt",
    "Five short steps. About two minutes.": "Fünf kurze Schritte. Etwa zwei Minuten.",
    "xAI and OpenAI need a key. On device needs a download. The first one in the list is tried first.": "xAI und OpenAI brauchen einen Schlüssel. Auf dem Telefon braucht einen Download. Der erste in der Liste wird zuerst probiert.",
    "Needed to hear you, including when the screen is off.": "Nötig, um dich zu hören, auch bei ausgeschaltetem Bildschirm.",
    "Three short recordings. They never leave the phone. You can skip and tap instead.": "Drei kurze Aufnahmen. Sie verlassen das Telefon nicht. Du kannst sie überspringen und stattdessen tippen.",
    "Add a voice key": "Sprachschlüssel hinzufügen",
    "Tap Use on device. That adds it to the list. No key.": "Tippe auf Auf dem Telefon nutzen. Das setzt es auf die Liste. Kein Schlüssel.",
    "Leave it first if the phone should answer before a cloud key.": "Lass es oben, wenn das Telefon vor einem Cloud-Schlüssel antworten soll.",
    "Download the packs below. Until they finish, Talk uses the next key.": "Lade die Pakete unten. Bis sie fertig sind, nutzt Sprechen den nächsten Schlüssel.",
    "Add another voice if you want a fallback, then tap Next.": "Füg eine weitere Stimme hinzu, wenn du einen Ersatz willst, und tippe dann auf Weiter.",
    "Each key stays on this phone. xAI is checked before it is stored. If the first voice fails, the next one is tried.": "Jeder Schlüssel bleibt auf diesem Telefon. xAI wird geprüft, bevor er gespeichert wird. Wenn die erste Stimme scheitert, kommt die nächste.",
    "Paste the {name} key": "{name}-Schlüssel einfügen",
    "Android will show a system prompt. Choose Allow.": "Android zeigt eine Systemabfrage. Wähl Zulassen.",
    "The microphone hears “Hey Grok” and your question. A quiet notification stays up so Android does not switch the microphone off when the screen locks.": "Das Mikrofon hört „Hey Grok“ und deine Frage. Eine leise Benachrichtigung bleibt, damit Android das Mikrofon beim Sperren nicht ausschaltet.",
    "Microphone is blocked. Open Android Settings → Apps → Grok Voice → Permissions, allow Microphone, then come back and tap the button again.": "Das Mikrofon ist blockiert. Öffne Android-Einstellungen → Apps → Grok Voice → Berechtigungen, erlaub das Mikrofon, komm zurück und tippe erneut.",
    "Notifications are off. Listening still works while the app is open. Allow notifications later if you want “Hey Grok” with the screen locked.": "Benachrichtigungen sind aus. Hören funktioniert weiter, solange die App offen ist. Erlaub sie später, wenn du „Hey Grok“ bei gesperrtem Bildschirm willst.",
    "How to talk": "So sprichst du",
    "Tap the ring": "Tippe auf den Ring",
    "Speak after it says Listening. Tap again to hang up.": "Sprich, wenn Hört zu steht. Tippe erneut, um aufzulegen.",
    "Ask it to do things": "Bitte es, Dinge zu erledigen",
    "Notes, alarms, timers, reminders, and calendar. Each has its own tab after setup.": "Notizen, Wecker, Timer, Erinnerungen und Kalender. Jedes hat nach dem Start einen eigenen Tab.",
    "Use headphones the first time. On a loudspeaker the microphone hears the reply and Grok answers itself. Echo guard is on so the mic mutes while Grok is talking. Turn it off in Settings, then Debug, if you want to interrupt.": "Nimm beim ersten Mal Kopfhörer. Über Lautsprecher hört das Mikrofon die Antwort und Grok antwortet sich selbst. Der Echo-Schutz ist an und stummschaltet das Mikrofon, während Grok spricht. Schalt ihn unter Einstellungen, dann Debug aus, wenn du unterbrechen willst.",
    "Enroll “Hey Grok”": "„Hey Grok“ einrichten",
    "Record yourself saying “Hey Grok” three times, in a quiet room, holding the phone the way you normally would. The recordings stay on this phone.": "Nimm dich dreimal auf, wie du „Hey Grok“ sagst, in einem ruhigen Raum, das Telefon so haltend wie sonst. Die Aufnahmen bleiben auf diesem Telefon.",
    "Sample {n}": "Probe {n}",
