    "“Hey Grok” enrolled. Turn on Listen on the Talk tab.": "„Hey Grok“ ist eingerichtet. Schalt Hören im Tab Sprechen ein.",
    "trained": "trainiert",
    "not trained": "nicht trainiert",
    "Status: {state}. Too many false wakes? Go back to Settings, open Debug, and raise Wake threshold.": "Status: {state}. Zu viele Fehlalarme? Geh zurück zu den Einstellungen, öffne Debug und erhöhe die Weckschwelle.",
    "That was too quiet — hold the phone closer and say “Hey Grok”.": "Das war zu leise. Halt das Telefon näher und sag „Hey Grok“.",
