    "On-device Talk reads these pinned facts and short notes from recent local sessions. Cloud Talk does not. Wiping this does not delete notes, People, Finance, or voice keys.": "Sprechen auf dem Telefon liest diese gemerkten Sätze und kurze Notizen aus letzten Sitzungen. Die Cloud-Stimme nicht. Löschen hier löscht nicht Notizen, Personen, Finanzen oder Sprachschlüssel.",
    "I live in Zurich": "Ich wohne in Zürich",
    "Tap again. Notes, People, Finance, and voice keys stay.": "Noch einmal tippen. Notizen, Personen, Finanzen und Sprachschlüssel bleiben.",
    "These are asked only when you turn them on. Notification access and Do Not Disturb open system settings. Call and text history is a separate permission and is not read until you allow it.": "Sie werden nur gefragt, wenn du sie einschaltest. Benachrichtigungszugriff und Nicht stören öffnen die Systemeinstellungen. Anruf- und Nachrichtenverlauf ist eine eigene Berechtigung und wird erst gelesen, wenn du sie erlaubst.",
    "An encrypted file of notes, People, and the small on-device memory. Older files have no memory section, so restoring one leaves the memory on this phone. Voice keys stay in the vault unless you include them here. Nothing is uploaded.": "Eine verschlüsselte Datei mit Notizen, Personen und dem kleinen Telefonspeicher. Ältere Dateien haben keinen Speicherabschnitt, eine Wiederherstellung lässt den Speicher auf diesem Telefon also stehen. Sprachschlüssel bleiben im Tresor, außer du nimmst sie hier mit. Nichts wird hochgeladen.",
