    "Each key stays on this phone. xAI is checked before it is stored. If the first voice fails, the next one is tried.": "Cada chave fica neste telefone. A xAI é verificada antes de ser salva. Se a primeira voz falhar, a próxima é tentada.",
    "Paste the {name} key": "Cole a chave de {name}",
    "Android will show a system prompt. Choose Allow.": "O Android vai mostrar um aviso do sistema. Escolha Permitir.",
    "The microphone hears “Hey Grok” and your question. A quiet notification stays up so Android does not switch the microphone off when the screen locks.": "O microfone ouve “Hey Grok” e a sua pergunta. Uma notificação discreta fica para o Android não desligar o microfone ao bloquear a tela.",
    "Microphone is blocked. Open Android Settings → Apps → Grok Voice → Permissions, allow Microphone, then come back and tap the button again.": "O microfone está bloqueado. Abra Ajustes do Android → Apps → Grok Voice → Permissões, permita o Microfone, volte e toque no botão de novo.",
    "Notifications are off. Listening still works while the app is open. Allow notifications later if you want “Hey Grok” with the screen locked.": "As notificações estão desligadas. Ouvir continua funcionando com o app aberto. Permita depois se quiser “Hey Grok” com a tela bloqueada.",
    "How to talk": "Como falar",
    "Tap the ring": "Toque no anel",
    "Speak after it says Listening. Tap again to hang up.": "Fale quando disser Ouvindo. Toque de novo para desligar.",
    "Ask it to do things": "Peça para ele fazer coisas",
    "Notes, alarms, timers, reminders, and calendar. Each has its own tab after setup.": "Notas, alarmes, timers, lembretes e calendário. Cada um tem a sua aba depois do início.",
    "Use headphones the first time. On a loudspeaker the microphone hears the reply and Grok answers itself. Echo guard is on so the mic mutes while Grok is talking. Turn it off in Settings, then Debug, if you want to interrupt.": "Use fones na primeira vez. No alto-falante o microfone ouve a resposta e o Grok responde a si mesmo. A proteção contra eco está ligada e silencia o microfone enquanto o Grok fala. Desligue em Ajustes e depois Depuração se quiser interromper.",
    "Enroll “Hey Grok”": "Gravar “Hey Grok”",
    "Record yourself saying “Hey Grok” three times, in a quiet room, holding the phone the way you normally would. The recordings stay on this phone.": "Grave-se dizendo “Hey Grok” três vezes, num lugar quieto, segurando o telefone como de costume. As gravações ficam neste telefone.",
