    "Turn on Listen on the Talk tab. A notification means it is listening.": "Activa Escoltar en la pestanya Parlar. Una notificació vol dir que està escoltant.",
    "You skipped enrollment. Train it anytime under Settings, then Wake word, and turn Listen on.": "Has saltat la gravació. Pots entrenar-la quan vulgues en Configuració, Paraula d'activació, i activa Escoltar.",
    "Save a voice to continue. On device counts after you tap Use on device.": "Guarda una veu per a continuar. En el telèfon compta quan toques Usa en el telèfon.",
    "Allow the microphone to continue.": "Permet el micròfon per a continuar.",
    "Preview finished. In the app this opens the assistant.": "La vista prèvia ha acabat. En l'app açò obri l'assistent.",
    "A voice assistant that stays on your phone": "Un assistent de veu que es queda en el teu telèfon",
    "Five short steps. About two minutes.": "Cinc passos curts. Uns dos minuts.",
    "xAI and OpenAI need a key. On device needs a download. The first one in the list is tried first.": "xAI i OpenAI necessiten una clau. En el telèfon necessita una descàrrega. Es prova primer el de dalt.",
    "Needed to hear you, including when the screen is off.": "Fa falta per a sentir-te, també amb la pantalla apagada.",
    "Three short recordings. They never leave the phone. You can skip and tap instead.": "Tres gravacions curtes. No ixen del telèfon. Pots saltar-les i tocar en el seu lloc.",
    "Add a voice key": "Afig una clau de veu",
    "Tap Use on device. That adds it to the list. No key.": "Toca Usa en el telèfon. Això l'afig a la llista. Sense clau.",
    "Leave it first if the phone should answer before a cloud key.": "Deixa'l el primer si el telèfon ha de respondre abans que una clau al núvol.",
    "Download the packs below. Until they finish, Talk uses the next key.": "Descarrega els paquets de baix. Fins que acaben, Parlar usa la clau següent.",
    "Add another voice if you want a fallback, then tap Next.": "Afig una altra veu si vols una reserva i després toca Següent.",
    "Each key stays on this phone. xAI is checked before it is stored. If the first voice fails, the next one is tried.": "Cada clau es queda en este telèfon. xAI es comprova abans de guardar-la. Si la primera veu falla, es prova la següent.",
    "Paste the {name} key": "Apega la clau de {name}",
    "Android will show a system prompt. Choose Allow.": "Android mostrarà un avís del sistema. Tria Permet.",
    "The microphone hears “Hey Grok” and your question. A quiet notification stays up so Android does not switch the microphone off when the screen locks.": "El micròfon sent “Hey Grok” i la teua pregunta. Queda una notificació discreta perquè Android no apague el micròfon en bloquejar la pantalla.",
    "Microphone is blocked. Open Android Settings → Apps → Grok Voice → Permissions, allow Microphone, then come back and tap the button again.": "El micròfon està bloquejat. Obri Configuració d'Android → Aplicacions → Grok Voice → Permisos, permet el micròfon, torna i toca el botó una altra vegada.",
    "Notifications are off. Listening still works while the app is open. Allow notifications later if you want “Hey Grok” with the screen locked.": "Les notificacions estan apagades. Escoltar continua funcionant amb l'app oberta. Permet-les després si vols “Hey Grok” amb la pantalla bloquejada.",
    "How to talk": "Com parlar",
    "Tap the ring": "Toca l'anell",
    "Speak after it says Listening. Tap again to hang up.": "Parla quan diga Escoltant. Toca una altra vegada per a penjar.",
    "Ask it to do things": "Demana-li que faça coses",
    "Notes, alarms, timers, reminders, and calendar. Each has its own tab after setup.": "Notes, alarmes, temporitzadors, recordatoris i calendari. Cadascun té la seua pestanya després de l'inici.",
    "Use headphones the first time. On a loudspeaker the microphone hears the reply and Grok answers itself. Echo guard is on so the mic mutes while Grok is talking. Turn it off in Settings, then Debug, if you want to interrupt.": "Usa auriculars la primera volta. En altaveu el micròfon sent la resposta i Grok es contesta. La protecció contra l'eco està encesa i silencia el micròfon mentre Grok parla. Apaga-la en Configuració i després Depuració si vols interrompre.",
    "Enroll “Hey Grok”": "Grava “Hey Grok”",
    "Record yourself saying “Hey Grok” three times, in a quiet room, holding the phone the way you normally would. The recordings stay on this phone.": "Grava't dient “Hey Grok” tres voltes, en un lloc tranquil, amb el telèfon com el subjectes normalment. Les gravacions es queden en este telèfon.",
