    "On-device Talk reads these pinned facts and short notes from recent local sessions. Cloud Talk does not. Wiping this does not delete notes, People, Finance, or voice keys.": "Parlar en el telèfon llig estes dades fixades i les notes curtes de les sessions recents. La veu al núvol no. Esborrar açò no esborra les notes, Persones, Finances ni les claus de veu.",
    "I live in Zurich": "Visc a Zuric",
    "Tap again. Notes, People, Finance, and voice keys stay.": "Toca una altra vegada. Les notes, Persones, Finances i les claus de veu es queden.",
    "These are asked only when you turn them on. Notification access and Do Not Disturb open system settings. Call and text history is a separate permission and is not read until you allow it.": "Només es demanen quan els actives. L'accés a les notificacions i No molestar obrin la configuració del sistema. L'historial de trucades i missatges és un altre permís i no es llig fins que el permets.",
    "An encrypted file of notes, People, and the small on-device memory. Older files have no memory section, so restoring one leaves the memory on this phone. Voice keys stay in the vault unless you include them here. Nothing is uploaded.": "Un fitxer xifrat de notes, Persones i la memòria menuda del telèfon. Els fitxers antics no tenen secció de memòria, així que restaurar-ne un deixa la memòria d'este telèfon. Les claus de veu es queden en la caixa forta llevat que les inclogues ací. No es puja res.",
